fn main() {
    // Euclidean algorithm
    fn gcd(mut a: u64, mut b: u64) -> u64 {
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a
    }
    println!("{}", gcd(252, 105));
}

