fn perfect_sum(n: Int) -> Int {
  let mut sum = 1;
  let mut d = 2;
  while d * d <= n {
    if n % d == 0 {
      sum += d;
      if d * d != n {
        sum += n / d;
      }
    }
    d += 1;
  }
  sum
}

