fn get_nth(v: Vec<Int>, n: Int) -> Option<Int> {
    if n < 0 || n >= len(v) {
        None
    } else {
        Some(get(v, n)?)
    }
}

fn first_big(v: Vec<Int>) -> Int {
    match get_nth(v, 0) {
        Some(x) => x,
        None => -1,
    }
}

fn second(v: Vec<Int>) -> Option<Int> {
    let x = get_nth(v, 1)?
    Some(x + 1)
}

